INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9306, 9013, 'tt0095631', NULL, 'Midnight Run', 'Midnight Run', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/yx0touyDQ9enWDsFgS4MbBwCSNd.jpg', 'https://image.tmdb.org/t/p/original/5bJuEI1jHkZIktD3vnshdWkJSH8.jpg', 'A bounty hunter pursues a former Mafia accountant who is also being chased by a rival bounty hunter, the F.B.I., and his old mob boss after jumping bail.', NULL, NULL, 7.956, 7.2, 0, 8.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
