INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9310, 63840, 'tt4228802', NULL, 'The Kettering Incident', 'The Kettering Incident', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/cHvjyl7y7kqXpciGfYsFCyYmjVp.jpg', 'https://image.tmdb.org/t/p/original/vUexm0yruCeFZCimaGC0p4a9Q6t.jpg', 'Anna Macy left Kettering when she was just 14, shortly after her best friend, Gillian Baxter mysteriously disappeared. The two girls had been playing in the forbidden forests outside Kettering when they saw strange lights in the sky. Eight hours later, Anna was found alone, terrified and covered in blood. 15 years on, Anna returns to find the town struggling to survive. The forests have been marked for logging and the community is being torn apart by passionate but violent clashes between environmentalists and the local loggers.', NULL, NULL, 3.7153, 6.462, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
