INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9324, 10974, 'tt0091431', NULL, 'Armour of God', '龍兄虎弟', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/phCpGqCSBWJqutKxj73COACrlPt.jpg', 'https://image.tmdb.org/t/p/original/yDU9lUG7IHFFLkxlLEvJtxOmW4P.jpg', 'Jackie Chan stars as Asian Hawk, an Indiana Jones-style adventurer looking to make a fortune in exotic antiquities. After Hawk discovers a mysterious sword in Africa, a band of Satan-worshipping monks kidnap his ex-girlfriend Lorelei, demanding the sword as ransom as well as other pieces of the legendary Armour of God - a magical outfit dating back to the Crusades.', NULL, NULL, 10.0077, 7.041, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9325, 13936, 'tt0048445', NULL, 'Oklahoma!', 'Oklahoma!', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/ztqT5GmJVI2o8vShGWRVVqykQqA.jpg', 'https://image.tmdb.org/t/p/original/scjRKib0bVVQEZv1lCutko4tlY4.jpg', 'There''s a box social coming up, and Curly asks Laurey if she''ll be his date. Trouble is, Laurey thinks he''s waited too long, and in a fit of pique accepts an offer from the boorish ranch hand Jud instead. Meanwhile, Laurey''s friend Ado Annie is also torn between two men: cowboy Will and foreign peddler Ali Hakim. Both women struggle to know their own hearts before it''s too late.', NULL, NULL, 3.6678, 6.619, 0, 1.04, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9326, 650672, 'tt10756134', NULL, 'The Ghost in the Darkness', 'The Ghost in the Darkness', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/swf8REzxo95Ghapo1c5R4vQeJyJ.jpg', 'https://image.tmdb.org/t/p/original/rcIXalQXmjf4uxcvHdpiREIQWb0.jpg', 'While exploring the deep woods, Youtuber Morgan stumbles upon a camera containing footage of a Satanic ritual and possible murder.  When the police dismiss it as a fake, she and her friend Amber set out to prove otherwise, putting themselves right in harm''s way.', NULL, NULL, 0.8702, 0.0, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9327, 152748, 'tt2388637', NULL, 'Ain''t Them Bodies Saints', 'Ain''t Them Bodies Saints', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/xkGkVjeMcvEg7P3VxWy8wYBJ7Dv.jpg', 'https://image.tmdb.org/t/p/original/jRxc6dVw7AxRUuOtFxmGop0IZ5p.jpg', 'Bob Muldoon and Ruth Guthrie, an impassioned young outlaw couple on an extended crime spree, are finally apprehended by lawmen after a shootout in the Texas hills. Although Ruth wounds a local officer, Bob takes the blame. But four years later, Bob escapes from prison and sets out to find Ruth and their daughter, born during his incarceration.', NULL, NULL, 2.7703, 6.099, 0, 5.51500000000000056e+00, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9328, 91737, 'tt0064579', NULL, 'The Learning Tree', 'The Learning Tree', 'movie', 1969, 'https://image.tmdb.org/t/p/w500/kxA20n5Oiy4Xx9nAqeXAMJ00S2K.jpg', 'https://image.tmdb.org/t/p/original/she3ghUOGCIOiG00TN5cg5fkV8w.jpg', 'The story, set in Kansas during the 1920''s, covers less than a year in the life of a black teenager, and documents the veritable deluge of events which force him into sudden manhood. The family relationships and enmities, the fears, frustrations and ambitions of the black teenager in small-town America are explored with a strong statement about human values.', NULL, NULL, 1.156, 6.72, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
