INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9330, 57212, 'tt1568911', NULL, 'War Horse', 'War Horse', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/3aRHhvvngFPJFy5uAjo7GVr3PhL.jpg', 'https://image.tmdb.org/t/p/original/tcx15vswrQJCGET5lGxESQ4J5LG.jpg', 'On the brink of the First World War, Albert''s beloved horse Joey is sold to the Cavalry by his father. Against the backdrop of the Great War, Joey begins an odyssey full of danger, joy, and sorrow, and he transforms everyone he meets along the way. Meanwhile, Albert, unable to forget his equine friend, searches the battlefields of France to find Joey and bring him home.', NULL, NULL, 9.4834, 7.304, 0, 2.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9331, 9624, 'tt0110725', NULL, 'On Deadly Ground', 'On Deadly Ground', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/8jnO8EByAsfupWj9RjQxYAO4AUH.jpg', 'https://image.tmdb.org/t/p/original/ttCHDsVpepLV1PoRYSePPcXrtYH.jpg', 'Forrest Taft is an environmental agent who works for the Aegis Oil Company in Alaska. Aegis Oil''s corrupt CEO is the kind of person who doesn''t care whether or not oil spills into the ocean or onto the land—just as long as it''s making money for him.', NULL, NULL, 5.9621, 5.205, 0, 6.52999999999999936e+00, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9332, 14463, 'tt0437806', NULL, 'Alone in the Wilderness', 'Alone in the Wilderness', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/fOzc4vwTG9d9tlhX6EyPHu3cuiq.jpg', 'https://image.tmdb.org/t/p/original/tIiPFKY7HynPQDyLYhG4CSbJNVM.jpg', 'Dick Proenneke retired at age 50 in 1967 and decided to build his own cabin in the wilderness at the base of the Aleutian Peninsula, in what is now Lake Clark National Park. Using color footage he shot himself, Proenneke traces how he came to this remote area, selected a homestead site and built his log cabin completely by himself. The documentary covers his first year in-country, showing his day-to-day activities and the passing of the seasons as he sought to scratch out a living alone in the wilderness.', NULL, NULL, 2.0522, 7.9, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9333, 61335, 'tt3498622', NULL, 'Fortitude', 'Fortitude', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/u6vKMeFEfz9sJun65EZgp4ltr9r.jpg', 'https://image.tmdb.org/t/p/original/ndsUXdC1DfnC6t5DETxeAvWqv73.jpg', 'Fortitude is a place like nowhere else. Although surrounded by the savage beauty of the Arctic landscape, Fortitude is one of the safest towns on earth. There has never been a violent crime here. Until now. In such a close-knit community a murder touches everyone and the unsettling, mysterious horror of this crime threatens the future of the town itself.', NULL, NULL, 10.1885, 6.811, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9334, 15198, 'tt0134618', NULL, 'Mystery, Alaska', 'Mystery, Alaska', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/bmg4sjOQswcrP5mPL9YzNom9cXx.jpg', 'https://image.tmdb.org/t/p/original/swwCQk5sDGeuVWub4GLyS2YETrT.jpg', 'In Mystery, Alaska, life revolves around the legendary Saturday hockey game at the local pond. But everything changes when the hometown team unexpectedly gets booked in an exhibition match against the New York Rangers. When quirky small-towners, slick promoters and millionaire athletes come together.', NULL, NULL, 3.6687, 6.289, 0, 2.025, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9335, 244761, 'tt2326612', NULL, 'The Captive', 'The Captive', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/wLoFxTZFEfAzFLk2qSoPbcz58Jb.jpg', 'https://image.tmdb.org/t/p/original/fD4Q03vX0xqumc6iuDt6SujrlxI.jpg', 'Eight years after their daughter Cassandra''s abduction tore them apart, an estranged couple discover disturbing clues that indicate that she is still alive.', NULL, NULL, 6.2273, 5.845, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9336, 36344, 'tt0115493', NULL, 'Alaska', 'Alaska', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/qInhNnU2siIX4vJudzm0fwzS99O.jpg', 'https://image.tmdb.org/t/p/original/gTodo59kxoc1siYPVmSOhVTEYsi.jpg', 'Jake Barnes and his two kids, Sean and Jessie, have moved to Alaska after his wife died. He is a former airline pilot now delivering toilet paper across the mountains. During an emergency delivery in a storm his plane goes down somewhere in the mountains. Annoyed that the authorities aren''t doing enough, Jessie and Sean set out on an adventure to find their father with the help of a polar bear which they have saved from a ferocious poacher. Conflict ensues.', NULL, NULL, 2.6994, 5.774, 0, 2.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9337, 77951, 'tt1762399', NULL, 'Walking with Dinosaurs', 'Walking with Dinosaurs', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/lkElT9HpOUIjIL20Hwy3LZqgXWc.jpg', 'https://image.tmdb.org/t/p/original/AdqdU9nexxg8obiEWQoIQQqsr4Q.jpg', 'In a time when dinosaurs rule the Earth, the smallest dinosaur of the herd, a playful Pachyrhinosaurus named Patchi, embarks on the biggest adventure of his life. As he tries to find his place in a spectacular world filled with fun-loving friends and a few dangerous foes, Patchi will discover the courage he needs to become the leader of the herd and a hero for the ages.', NULL, NULL, 4.6552, 6.191, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9338, 45169, 'tt0079770', NULL, 'Quintet', 'Quintet', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/kjAzxXZzzoixPca518dwKRnJ0Km.jpg', 'https://image.tmdb.org/t/p/original/4gIrc2OGZJgloQadWdS427rPJ6Q.jpg', 'During a future ice age, dying humanity occupies its remaining time by playing a board game called Quintet. For one small group, this obsession is not enough. They play the game with living pieces, and only the winner survives.', NULL, NULL, 2.0531, 4.956, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9339, 14694, 'tt0337721', NULL, 'The Snow Walker', 'The Snow Walker', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/1UlHIWfqjkizc2qem0IPZBG6nn5.jpg', 'https://image.tmdb.org/t/p/original/kkFwxts0A2E6k2maR0UktH4cV4F.jpg', 'A bush pilot in nothern Canada who with the aid of modernity thinks he can handle it all & knows it all. After reluctantly agreeing to transport a local indian girl to a medical facility his light plane crashes & they have to survive whilst finding their way back to civilization. Along the journey the man finds a new respect for the native ways as they battle to survive the elements.', NULL, NULL, 3.4107, 6.996, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9340, 4318, 'tt0065327', NULL, 'Night Gallery', 'Night Gallery', 'tv', 1970, 'https://image.tmdb.org/t/p/w500/jqRjJboIOcgMf5o2UZe84F1AzBt.jpg', 'https://image.tmdb.org/t/p/original/kKJPh79nejTTxHWhKyhZGdOy5gd.jpg', 'Rod Serling narrates an anthology of fantasy, horror and sci-fi stories from a set resembling a macabre museum. A chilling work of art serves as the connective link between the stories.', NULL, NULL, 19.1392, 7.8, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9341, NULL, NULL, 166675, 'Tux and Fanny', 'Tux and Fanny', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3s87.jpg', NULL, 'Tux and Fanny just want to play soccer but their soccer ball is deflated. Go on an epic adventure to help them inflate their ball. Play as both Tux and Fanny as well as a cat and a flea. All four characters will have to work together if you''re going to inflate the ball.', 'https://www.igdb.com/games/tux-and-fanny', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9342, 126506, 'tt12074628', NULL, 'Smiling Friends', 'Smiling Friends', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/q3CSxl3G06MBc73TpHWwBYYTPxL.jpg', 'https://image.tmdb.org/t/p/original/qjHTkQ3QUlw6sxkIhugqNYsRJnR.jpg', 'Smiling Friends Inc. is a small company whose main purpose is to bring happiness and make people smile. The series follows the day-to-day lives and misadventures of its representatives, the lazy, cynical Charlie, and the cheerful, optimistic Pim, as they try to cheer up and comfort the troubled people who call their company''s hotline. They receive seemingly simple requests but the jobs turn out to be more complicated than they seem, making it difficult to bring happiness to the world.', NULL, NULL, 24.0053, 8.521, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9343, 3465, 'tt0103505', NULL, 'On the Air', 'On the Air', 'tv', 1992, 'https://image.tmdb.org/t/p/w500/kSvDzCnUCMzH6bvkGQv3Ps0sJJS.jpg', 'https://image.tmdb.org/t/p/original/bZ7vf3fzqMLHpbYFMxk2M39B6dQ.jpg', 'The year is 1957. The cast and crew of the Lester Guy Show are extremely apprehensive about their upcoming live television broadcast on the Zoblotnick Broadcasting Co. network. Lester Guy despises fellow cast member Betty Hudson for unknowingly becoming more popular than him and schemes to destroy her career. Only two of the seven episodes were written by David Lynch.', NULL, NULL, 3.1472, 6.167, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9344, 61196, 'tt0350044', NULL, 'Reflections of Evil', 'Reflections of Evil', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/cf9twDmKQgxU7jkeSrkmD5KtcsJ.jpg', 'https://image.tmdb.org/t/p/original/x4sJOw6I9Kyvxhte1zdRCjGTlOn.jpg', 'Julie, a teen who died from a PCP overdose in the early ''70s, searches from beyond the grave for her younger brother Bob, who now in the ''90s is an obese watch seller suffering with sucrose intolerance.', NULL, NULL, 1.3517, 6.5, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9345, 862, 'tt0114709', NULL, 'Toy Story', 'Toy Story', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', 'https://image.tmdb.org/t/p/original/3Rfvhy1Nl6sSGJwyjb0QiZzZYlB.jpg', 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.', NULL, NULL, 40.4699, 8.0, 0, 7.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9346, 603204, 'tt10354106', NULL, 'Stars at Noon', 'Stars at Noon', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/viR50oQCs8ObciADFGWHUyChexZ.jpg', 'https://image.tmdb.org/t/p/original/tOfJuyfEbUMSSyBK24CAehphKwD.jpg', 'In present-day Nicaragua, a headstrong American journalist and a mysterious English businessman strike up a romance as they become embroiled in a dangerous labyrinth of lies and conspiracies and are forced to try and escape the country.', NULL, NULL, 3.5388, 5.823, 0, 11.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9347, 504172, 'tt7959026', NULL, 'The Mule', 'The Mule', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/vkOfx5meJvFb4qmAJU7j6v8IIpZ.jpg', 'https://image.tmdb.org/t/p/original/h51DdjaDD2aPu1fLHsmpJaaJinS.jpg', 'Earl Stone, a man in his eighties, is broke, alone, and facing foreclosure of his business when he is offered a job that simply requires him to drive. Easy enough, but, unbeknownst to Earl, he''s just signed on as a drug courier for a Mexican cartel. He does so well that his cargo increases exponentially, and Earl hit the radar of hard-charging DEA agent Colin Bates.', NULL, NULL, 7.9501, 6.869, 0, 12.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9348, 17874, 'tt0077834', NULL, 'Laserblast', 'Laserblast', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/jxv1Z0URENuWADDRwvRINUWUsP.jpg', 'https://image.tmdb.org/t/p/original/7nzsQIF5tLzw60ok5jdHeFwpqed.jpg', 'Happy go-lucky teen Billy Duncan discovers an otherworldly laser gun in the southern California desert, making him the target of a pair of aliens who had recently executed its previous owner.', NULL, NULL, 2.3113, 3.4, 0, 11.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9349, 10677, 'tt0338096', NULL, 'Dirty Dancing: Havana Nights', 'Dirty Dancing: Havana Nights', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/5FnSCH592YIivbKtotq7YQanvmu.jpg', 'https://image.tmdb.org/t/p/original/595WmPkDojtR9XVu2ssKfSIWu3a.jpg', 'In pre-revolution Cuba, Katey Miller is about to defy everyone''s expectations. Instead of a parent-approved suitor, Katey is drawn to the sexy waiter, Javier, who spends his nights dancing in Havana''s nightclubs. As she secretly learns to dance with Javier, she learns the meanings of love, sensuality and independence.', NULL, NULL, 4.2502, 6.428, 0, 11.0, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9350, 104819, 'tt0982908', NULL, 'Orozco the Embalmer', 'Orozco el embalsamador', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/ytqzgrjlbSv8Ay6Zc0EksQGBHzn.jpg', 'https://image.tmdb.org/t/p/original/6xE3fijk2SBlZxF62MCfLQZ61AH.jpg', 'In 1996, Tsurisaki Kiyotaka, one of Japan’s most infamous death photographers, ventured into the center of Hell itself - the Rue Morgue neighborhood of Bogota, Colombia. With death and murder rampant, the corpses eventually find their way to embalmer Froilan Orozco, who has been tending the dead for over 50 years. We watch as bodies are brought in to his shop and he prepares them for their funerals.', NULL, NULL, 4.1815, 6.417, 0, 11.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
