INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9353, 8856, 'tt0091326', NULL, 'The Karate Kid Part II', 'The Karate Kid Part II', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/k0OwgRR6PNu7h3SiqpCbRdZWNaG.jpg', 'https://image.tmdb.org/t/p/original/7rfcRXbFD0xr8NteNq1hwXUd4Af.jpg', 'Summoned by his dying father, Miyagi returns to his homeland of Okinawa, with Daniel, after a 40-year exile. There he must confront Yukie, the love of his youth, and Sato, his former best friend turned vengeful rival. Sato is bent on a fight to the death, even if it means the destruction of their village. Daniel finds his own love in Yukia''s niece, Kumiko, and his own enemy in Sato''s nephew, the vicious Chozen. Now, far away from the tournaments, cheering crowds and safety of home, Daniel will face his greatest challenge ever when the cost of honor is life itself.', NULL, NULL, 8.0784, 6.347, 0, 11.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
