INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9379, 50348, 'tt1189340', NULL, 'The Lincoln Lawyer', 'The Lincoln Lawyer', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/gOn8Ve9Yi8fxjRkmLr5BZoOc7KV.jpg', 'https://image.tmdb.org/t/p/original/j9QaQVuyQIEwckUbjHpAgA7E4jJ.jpg', 'Mick Haller is a charismatic defense attorney who does business out of his Lincoln Continental sedan. Mick spends most of his time defending petty crooks and other bottom-feeders, so it comes as quite a surprise when he lands the case of a lifetime: defending a Beverly Hills playboy who is accused of attempted murder. However, what Mick initially thinks is an open-and-shut case with a big monetary reward develops into something more sinister.', NULL, NULL, 7.3634, 7.208, 0, 9.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
