INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9381, 3543, 'tt0095801', NULL, 'Bagdad Cafe', 'Out of Rosenheim', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/zeEa3jVkLE8C0KjOiiKqMbhHgaL.jpg', 'https://image.tmdb.org/t/p/original/xNZwsgmAt3aqjKZYWQmUzEij6XD.jpg', 'A German woman named Jasmin stumbles upon a dilapidated motel/diner in the middle of nowhere. Her unusual appearance and demeanor are at first suspicious to Brenda, the exasperated owner who has difficulty making ends meet. But when an unlikely magic sparks between the two women, this lonely desert outpost is transformed into a thriving and popular oasis.', NULL, NULL, 3.0603, 7.192, 0, 1.1536666666666667e+01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9382, 627659, 'tt6470644', NULL, 'Paper House', '纸屋', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/jJS0rZDcHMrmSlDouax6zpGOEkT.jpg', 'https://image.tmdb.org/t/p/original/sA3F8KvhHgN0BTJ9iMLlT7a0k9s.jpg', 'Paper House is a short film set against the backdrop of a traditional Chinese funeral and its customs. The film follows the story of a family as they descend into disharmony after the death of their patriarch. The title of the film refers to the old Chinese tradition of burning paper offerings for their deceased loved ones. This short film is a eulogy for this colourful art form that is fast disappearing in Singapore’s modern society.', NULL, NULL, 1.6739, 0.0, 0, 10.025, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9383, 49980, 'tt0110296', NULL, 'Ladybird Ladybird', 'Ladybird Ladybird', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/14sAtrim0RpkI1eZSZ3m5etp5Wz.jpg', 'https://image.tmdb.org/t/p/original/cNftai0xQHlb3wiqWlFioAWNWwF.jpg', 'Maggie has had four children, by four different fathers, removed by social services because of a previous violent relationship. When she meets Jorge, a gentle Latin American refugee, she gradually sees her chance for happiness, but her past still haunts her.', NULL, NULL, 1.886, 7.2, 0, 9.02333333333333342e+00, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9384, 426613, 'tt6257174', NULL, 'The Miseducation of Cameron Post', 'The Miseducation of Cameron Post', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/xFLJDW3na8AADFzQJT6bM1VU5zs.jpg', 'https://image.tmdb.org/t/p/original/lqmNJ2dEqC5afCmYeLUiC6bYDUI.jpg', 'Pennsylvania, 1993. After getting caught with another girl, teenager Cameron Post is sent to a conversion therapy center run by the strict Dr. Lydia Marsh and her brother, Reverend Rick, whose treatment consists in repenting for feeling “same sex attraction.” Cameron befriends fellow sinners Jane and Adam, thus creating a new family to deal with the surrounding intolerance.', NULL, NULL, 4.5122, 6.892, 0, 4.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9385, NULL, NULL, 305157, 'Mixtape', 'Mixtape', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc2wi.jpg', NULL, 'Mixtape is a narrative adventure game developed by Beethoven & Dinosaur and published by Annapurna Interactive. Set during the last night of high school, it follows three friends as they revisit memories connected to music, youth and leaving home. The game combines story scenes with playable vignettes, including skating, parties, and other moments, all framed by a licensed soundtrack.', 'https://www.igdb.com/games/mixtape--1', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 4.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
