INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9387, 499546, 'tt6671244', NULL, 'We', 'Wij', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/gwTKiJF57VknDuNCWgoHaJamm82.jpg', 'https://image.tmdb.org/t/p/original/3kb5b8IQCX4vd3baNBoZqAboP41.jpg', 'During a scorching summer in a Belgian-Dutch border village, eight teenagers play games of discovery to break the listless monotony. They challenge each other and themselves and pretty soon, their sexual curiosity starts to blur the lines between right and wrong. As innocence is crushed in depraved games and sexual exploitation, the teenagers soon turn into ruthless predators.', NULL, NULL, 12.3145, 5.387, 0, 3.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
