INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9389, 79825, 'tt1673736', NULL, 'Falling Overnight', 'Falling Overnight', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/9UgIOvF6TEPYdsFAa8gwjfagiCA.jpg', 'https://image.tmdb.org/t/p/original/4fcxcRkskAjDjIimeFesdiVhV5I.jpg', 'Falling Overnight tells the story of twenty-two year old Elliot Carson on the day before he has risky surgery to remove a brain tumor. Facing what could be his last night, Elliot’s path intersects with Chloe Webb, a young photographer who invites him to her art show. Elliot welcomes the distraction and as the night descends, Chloe takes him on an intimate and exhilarating journey through the city. But as morning approaches, and Chloe learns of Elliot’s condition, the magic of the evening unravels, and they must together face the uncertainty of Elliot’s future.', NULL, NULL, 0.8242, 5.8, 0, 3.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
