INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9423, 996821, 'tt21227864', NULL, 'You''re Cordially Invited', 'You''re Cordially Invited', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/muXnwAdVdEEktto0NBNMyqK3uQH.jpg', 'https://image.tmdb.org/t/p/original/lsOdEAkwQ0TcP71HocJi8WUftmp.jpg', 'When two weddings are accidentally booked on the same day at the same venue, each bridal party is challenged with preserving their family''s special moment while making the most of the unanticipated tight quarters. In a hilarious battle of determination and grit, the father of the bride and sister of the other bride chaotically go head-to-head as they stop at nothing to uphold an unforgettable celebration for their loved ones.', NULL, NULL, 7.671, 5.822, 0, 1.1, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
