INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9434, 432976, 'tt6333060', NULL, 'Icarus', 'Icarus', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/x5azMi1KvZWbBbfjmGqpHNGqjH.jpg', 'https://image.tmdb.org/t/p/original/ambKXAJYrDPJK9wBJlIVVWbQbar.jpg', 'While investigating the furtive world of illegal doping in sports, director Bryan Fogel connects with renegade Russian scientist Dr. Grigory Rodchenkov—a pillar of his country’s “anti-doping” program. Over dozens of Skype calls, urine samples, and badly administered hormone injections, Fogel and Rodchenkov grow closer despite shocking allegations that place Rodchenkov at the center of Russia’s state-sponsored Olympic doping program.', NULL, NULL, 2.1423, 7.646, 0, 2.075, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9435, 740985, 'tt13143964', NULL, 'Borat Subsequent Moviefilm: Delivery of Prodigious Bribe to American Regime for Make Benefit Once Glorious Nation of Kazakhstan', 'Borat Subsequent Moviefilm: Delivery of Prodigious Bribe to American Regime for Make Benefit Once Glorious Nation of Kazakhstan', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/3L1Ml5RWjFVfVq3rQENvgFymT0U.jpg', 'https://image.tmdb.org/t/p/original/hbrXbVoE0NuA1ORoSGGYNASagrl.jpg', '14 years after making a film about his journey across the USA, Borat risks life and limb when he returns to the United States with his young daughter, and reveals more about the culture, the COVID-19 pandemic, and the political elections.', NULL, NULL, 12.8793, 6.428, 0, 1.06, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9436, 14268, 'tt0256408', NULL, 'Startup.com', 'Startup.com', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/ognPQebXUCRfKwAyRodR0j0xLjd.jpg', 'https://image.tmdb.org/t/p/original/cQm7tq2QHEr3oE3t6q3kKC9nONZ.jpg', 'Friends since high school, 20-somethings Kaleil Isaza Tuzman and Tom Herman have an idea: a Web site for people to conduct business with municipal governments. This documentary tracks the rise and fall of govWorks.com from May of 1999 to December of 2000, and the trials the business brings to the relationship of these best friends. Kaleil raises the money, Tom''s the technical chief. A third partner wants a buy out; girlfriends come and go; Tom''s daughter needs attention. And always the need for cash and for improving the site. Venture capital comes in by the millions. Kaleil is on C-SPAN, CNN, and magazine covers. Will the business or the friendship crash first?', NULL, NULL, 1.0001, 6.705, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9437, 34303, 'tt0179218', NULL, 'Hitman Hart: Wrestling with Shadows', 'Hitman Hart: Wrestling with Shadows', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/t1OcFAGsBWMUgtifSXblxiCHrZl.jpg', 'https://image.tmdb.org/t/p/original/mEEpAUGeYkLuaaW3A7EgqduchLW.jpg', 'This documentary follows superstar Bret Hart during his last year in the WWF. The film documents the tensions that resulted in The Montreal Screwjob, one of the most controversial events in the history of professional wrestling, in which Vince McMahon, Shawn Micheals, and others, legitimately conspired behind the scenes to go against the script and remove Bret Hart as champion.', NULL, NULL, 1.7232, 7.533, 0, 1.04, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9438, 100776, 'tt0293475', NULL, 'Original Cast Album: Company', 'Original Cast Album: Company', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/2kqkqG154DXzUOE9n9wXpfMLIao.jpg', 'https://image.tmdb.org/t/p/original/YlPZHMV67Mucl1WCnKYpiHeFB9.jpg', 'In 1970, right after the triumphant premiere of Stephen Sondheim’s groundbreaking concept musical Company, the renowned composer and lyricist, his director Harold Prince, the show’s stars, and a large pit orchestra all went into a Manhattan recording studio as part of a time-honored Broadway tradition: the making of the original cast album. What ensued was a marathon session in which all involved pushed themselves to the limit.', NULL, NULL, 1.0256, 7.214, 0, 1.04, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9439, 14285, 'tt0096257', NULL, 'The Thin Blue Line', 'The Thin Blue Line', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/4w4BJk3l8y9gYwPPLRs6uPHOmGL.jpg', 'https://image.tmdb.org/t/p/original/9ndhlUu1VQ44pX5dVFo5Y19KqAl.jpg', 'An unorthodox investigation into the wrongful conviction of Randall Dale Adams for the 1976 murder of Dallas police officer Robert Wood. Using stylized reenactments and interviews with key figures, conflicting testimonies and evidence are presented to argue that Adams was framed by a corrupt justice system, ultimately leading to his exoneration.', NULL, NULL, 2.6681, 7.652, 0, 1.04, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9440, 38634, 'tt0101655', NULL, 'Dancing Outlaw', 'Dancing Outlaw', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/57XjDFFQiABtbWnRMhUWoiwJmcS.jpg', NULL, 'This documentary short, produced for West Virginia public TV''s "Different Drummer" series, introduces us to Jesco White, a hard-living, tap-dancing Boone County resident whose repeated run-ins with the law have interfered with his dream of becoming as renowned a "mountain dancer" as his late father, D. Ray White. We meet Jesco''s three distinct personalities; the gentle and loving Jesse, the violent and dangerous Jesco, and the extremely strange Elvis. We also encounter various members of Jesco''s family, all nearly as eccentric as Jesco himself. You will ask, "Are these people for real?" Yes, they are.', NULL, NULL, 0.7796, 7.5, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9441, 58931, 'tt0272104', NULL, 'Gang War: Bangin'' in Little Rock', 'Gang War: Bangin'' in Little Rock', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/tf5MCKU4SUyjJSIaxciVKha7yKq.jpg', NULL, 'Raw and unflinching, this pair of award-winning HBO films looks at the death and destruction caused by gang warfare across the United States. With unlimited access, the filmmakers document the lives and culture of rival Arkansas factions in Gang War: Bangin'' in Little Rock. Back in the Hood: Gang War 2 follows Leifel Jackson, a former gang leader and ex-con trying to turn his life around after spending nearly a decade in prison.', NULL, NULL, 0.6074, 6.5, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9442, 1430, 'tt0310793', NULL, 'Bowling for Columbine', 'Bowling for Columbine', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/4XsiTsZcNCRSkee1o0fdr5OqYRT.jpg', 'https://image.tmdb.org/t/p/original/70uUnpfe7en9x011UjpZoub101l.jpg', 'This is not a film about gun control. It is a film about the fearful heart and soul of the United States, and the 280 million Americans lucky enough to have the right to a constitutionally protected Uzi. From a look at the Columbine High School security camera tapes to the home of Oscar-winning NRA President Charlton Heston, from a young man who makes homemade napalm with The Anarchist''s Cookbook to the murder of a six-year-old girl by another six-year-old. Bowling for Columbine is a journey through the US, through our past, hoping to discover why our pursuit of happiness is so riddled with violence.', NULL, NULL, 3.6742, 7.52, 0, 2.025, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9443, 35997, 'tt0320512', NULL, 'The Smashing Machine', 'The Smashing Machine', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/xfR7bDx7vh7HqRuZmnaRyMWju87.jpg', 'https://image.tmdb.org/t/p/original/5TzPlKBjQNCkli0SZRtwkV8LNM.jpg', 'An unflinching look at the life and story of Mark Kerr between 1999 and 2001, an intelligent, articulate, and emotionally vulnerable athlete, considered by many at the time to be the most dominant ultimate fighter in the world. A former Olympic wrestler, Kerr easily dominated all his opponents, earning him the nickname "The Smashing Machine." With the promise of big money and the euphoria of his early victories, Kerr must battle his injuries and inner fears. The shock of these fights takes a heavy toll on his body and mind, and Kerr attempts to overcome these physical and psychological traumas by turning to painkillers. Kerr''s addiction is shown in its raw form, with the camera capturing him desperately soliciting drugs from friends and staff, and injecting painkillers into his veins. His shocking defeat to Fujita in Japan shows us a story that is sometimes difficult and heartbreaking to watch.', NULL, NULL, 1.1746, 7.152, 0, 1.0, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9444, 44432, 'tt0988086', NULL, 'The Dungeon Masters', 'The Dungeon Masters', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/s5tZg3GVhD5o5qDYL5aYVYCu5Oa.jpg', NULL, 'The Dungeon Masters explores the subculture of role-playing games, specifically Dungeons &amp; Dragons, which for over 30 years has offered gamers the chance to escape their mundane lives and participate in a world they might otherwise never experience. Popularity and power are based on creativity and imagination rather than social status or wealth, and success is based not on who you know but on what you do.', NULL, NULL, 0.73, 5.1, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9445, 1029575, 'tt16431870', NULL, 'The Family Plan', 'The Family Plan', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/jLLtx3nTRSLGPAKl4RoIv1FbEBr.jpg', 'https://image.tmdb.org/t/p/original/arNhhBd88bP3Bjoe4HT8MFE1JQA.jpg', 'Dan Morgan is many things: a devoted husband, a loving father, a celebrated car salesman. He''s also a former assassin. And when his past catches up to his present, he''s forced to take his unsuspecting family on a road trip unlike any other.', NULL, NULL, 15.3582, 7.214, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9446, 18570, 'tt1286537', NULL, 'Food, Inc.', 'Food, Inc.', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/zdwN4o7OGAZGJw9T64lRAGTEP8b.jpg', 'https://image.tmdb.org/t/p/original/1xMMkeXynf8w11eXqEC3HCLhzt5.jpg', 'Documentary filmmaker Robert Kenner examines how mammoth corporations have taken over all aspects of the food chain in the United States, from the farms where our food is grown to the chain restaurants and supermarkets where it''s sold. Narrated by author and activist Eric Schlosser, the film features interviews with average Americans about their dietary habits, commentary from food experts like Michael Pollan and unsettling footage shot inside large-scale animal processing plants.', NULL, NULL, 1.9094, 7.369, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9447, 14242, 'tt0181288', NULL, 'American Movie', 'American Movie', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/y8dJgWr1HeW0RRxwANDWvgIXdsF.jpg', 'https://image.tmdb.org/t/p/original/bdSZ5SutGPvFPpRKZNcF1au6owe.jpg', 'American Movie documents the story of filmmaker Mark Borchardt, his mission, and his dream. Spanning over two years of intense struggle with his film, his family, financial decline, and spiritual crisis, American Movie is a portrayal of ambition, obsession, excess, and one man''s quest for the American Dream.', NULL, NULL, 3.8843, 7.535, 0, 4.0125, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9448, 1781, 'tt0497116', NULL, 'An Inconvenient Truth', 'An Inconvenient Truth', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/zrYT5UHE2UIsofwkv6KK2Tsu5a.jpg', 'https://image.tmdb.org/t/p/original/4Nx3XAGPwv5AfdrSq9LFDEACl3T.jpg', 'A documentary on Al Gore''s campaign to make the issue of global warming a recognized problem worldwide.', NULL, NULL, 4.9786, 6.955, 0, 1.0, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9449, 1048880, NULL, NULL, 'Zeitgeist', 'Zeitgeist', 'movie', 2007, NULL, NULL, 'A haunting short film by Navot Papushado, co-director of Rabies and Big Bad Wolves, which explores the persistence of Holocaust memory on the contemporary Israeli psyche. Unsettling and beautifully realized.', NULL, NULL, 0.5554, 0.0, 0, 1.0, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9450, 13958, 'tt0923752', NULL, 'The King of Kong: A Fistful of Quarters', 'The King of Kong: A Fistful of Quarters', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/wACtXGiO08EBbJhqsD2nUzPsrKe.jpg', 'https://image.tmdb.org/t/p/original/cXN62FQwOoBcKlIJ9uE3Cn5wHAc.jpg', 'In this hilarious arcade showdown, a humble novice goes head-to-head against the reigning Donkey Kong champ in a confrontation that rocks the gaming world to its processors! For over 20 years, Billy Mitchell has owned the throne of the Donkey Kong world. No one could beat his top score until now. Newcomer Steve Wiebe claims to have beaten the unbeatable, but Mitchell isn''t ready to relinquish his crown without a fight. Go behind the barrels as the two battle it out in a vicious war to earn the title of the true King of Kong.', NULL, NULL, 1.4095, 7.733, 0, 3.0166666666666666e+00, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9451, 1435, 'tt0390538', NULL, 'Tarnation', 'Tarnation', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/7zeQapdvD8poOizcaHwzmPxN9Km.jpg', 'https://image.tmdb.org/t/p/original/ayCacNxcVzNdw7wwTKYwzMihjRY.jpg', 'Filmmaker Jonathan Caouette''s documentary on growing up with his schizophrenic mother -- a mixture of snapshots, Super-8, answering machine messages, video diaries, early short films, and more -- culled from 19 years of his life.', NULL, NULL, 1.7611, 6.803, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
