INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9453, 97400, 'tt0332422', NULL, 'The Sweatbox', 'The Sweatbox', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/oAHBWF4RitZTSIUmDIfIdaSjvQb.jpg', 'https://image.tmdb.org/t/p/original/5ORnbDn0np8z2DzReM5WFKlbxsY.jpg', 'Trudie Styler, a documentarian, had been allowed to film the production of ''Kingdom of the Sun''/''The Emperor''s New Groove'' as part of the deal that originally brought her husband Sting to the project. As a result, Styler recorded much of the struggle, controversy, and troubles that went into making the picture on film (including when producer Fullmer called Sting to inform the pop star that his songs were being deleted from the film). Styler''s completed documentary, The Sweatbox, premiered at the Toronto Film Festival on September 13, 2002. Disney owns the rights to the documentary and has not released it on home video or DVD.', NULL, NULL, 1.5484, 7.0, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
