INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9455, 11304, 'tt0312318', NULL, '9/11', '9/11', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/k4Cs8h56Q1zpvWQMNSCi67uAqEe.jpg', 'https://image.tmdb.org/t/p/original/yBRIOaJVeMpfvPMeiqV7RtAMV81.jpg', 'An on-the-scene documentary following the events of September 11, 2001 from an insider''s view, through the lens of two French filmmakers who simply set out to make a movie about a rookie NYC fireman and ended up filming the tragic event that changed our lives forever.', NULL, NULL, 1.6566, 7.875, 0, 2.015, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
