INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9484, 40651, 'tt0113429', NULL, 'Institute Benjamenta, or This Dream People Call Human Life', 'Institute Benjamenta, or This Dream People Call Human Life', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/sbAYYXZNY6iofJa1EfylnR9MrkC.jpg', 'https://image.tmdb.org/t/p/original/cKQbtVObw0klPpjG5pT8SLs30he.jpg', 'Jakob arrives at the Institute Benjamenta (run by brother and sister Johannes and Lisa Benjamenta) to learn to become a servant. With seven other men, he studies under Lisa: absurd lessons of movement, drawing circles, and servility. He asks for a better room. No other students arrive and none leave for employment. Johannes is unhappy, imperious, and detached from the school''s operation. Lisa is beautiful, at first tightly controlled, then on the verge of breakdown. There''s a whiff of incest. Jakob is drawn to Lisa, and perhaps she to him. As winter sets in, she becomes catatonic. Things get worse; Johannes notes that all this has happened since Jakob came. Is there any cause and effect?', NULL, NULL, 1.3646, 7.633, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
