INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9512, 23048, 'tt1231587', NULL, 'Hot Tub Time Machine', 'Hot Tub Time Machine', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/wjzbVXAes1acbh6k4OO5xVfy5.jpg', 'https://image.tmdb.org/t/p/original/wwzuxanisjA7GhZOPYaWlfmlCKY.jpg', 'Four pals are stuck in a rut in adulthood: Adam has just been dumped, Lou is a hopeless party animal, Nick is a henpecked husband, and Jacob does nothing but play video games in his basement. But they get a chance to brighten their future by changing their past after a night of heavy drinking in a ski-resort hot tub results in their waking up in 1986.', NULL, NULL, 7.4178, 6.047, 0, 3.01000000000000023e+00, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9513, 16370, 'tt0106315', NULL, 'Aspen Extreme', 'Aspen Extreme', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/kbXb9XvMZW6GmLJoFf7gkoLBvUR.jpg', 'https://image.tmdb.org/t/p/original/emdEruzRaUoTJugJozTjAiQYw6E.jpg', 'T.J. and his friend Dexter quit their jobs in Detroit to become ski-instructors in Aspen. While T.J. advances to the most popular instructor of the school during the season, he has to take care for Dexter, who''s future is less bright and who''s eventually thinking about jobbing as drug courier - bringing their friendship to a test. Meanwhile the rich business woman Brice supports T.J. in his writing ambitions and invites him to live at her home. But in her absence he falls in love with the stunningly beautiful blond radio moderator Robin.', NULL, NULL, 1.4916, 5.91, 0, 2.95, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9514, 265189, 'tt2121382', NULL, 'Force Majeure', 'Turist', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/41agNfzepz2DTdgTBX1fX0QclHp.jpg', 'https://image.tmdb.org/t/p/original/oZp8CLwvRXgBAYGhn8P0pKOD4Ho.jpg', 'While holidaying in the French Alps, a Swedish family deals with acts of cowardliness as an avalanche breaks out.', NULL, NULL, 4.4439, 6.841, 0, 3.09499999999999975e+00, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9515, 83050, 'tt9117054', NULL, 'Spinning Out', 'Spinning Out', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/bAEGuEK0z4KTlrsx5UYpIvmPIPc.jpg', 'https://image.tmdb.org/t/p/original/zLAANW5gTW6l2vbMPRmJasyI171.jpg', 'A figure skating Olympic hopeful struggles to balance love, family and fragile mental health as her dream of winning takes a dizzying hold.', NULL, NULL, 7.8391, 7.9, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9516, 197796, 'tt2316801', NULL, 'Beauty and the Beast', 'La Belle et la Bête', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/8bErT2koHXAUSW5PdLQqgL5gEEe.jpg', 'https://image.tmdb.org/t/p/original/92Uceuy7HaiiHFgW48gNyxhx17d.jpg', 'Forced to face the cruel side of life, a devastated, bankrupt merchant chances upon the enchanted castle of a hideous creature, the mere sight of it chills the bone to the marrow. There, a fate worse than death awaits the poor father-of-six, who, after plucking a sweet-scented rose from the repulsive master''s verdant garden, must do the impossible: permit his compassionate daughter, Belle, to take his place and pay for the sins of her parent. Now, an impenetrable mystery shrouds the haunted mansion, and, as repugnance gradually turns into affection, only true love could break the spell.', NULL, NULL, 6.8848, 6.29, 0, 1.08, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9517, 9026, 'tt0278500', NULL, 'The Importance of Being Earnest', 'The Importance of Being Earnest', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/87r4e4pL4STfpdjtqNZxlyjvcMd.jpg', 'https://image.tmdb.org/t/p/original/zIwsL0bIScIMu4CV0C3DxWxKFSN.jpg', 'Two young gentlemen living in 1890s England use the same pseudonym (''Ernest'') on the sly, which is fine until they both fall in love with women using that name, which leads to a comedy of mistaken identities.', NULL, NULL, 2.4277, 6.823, 0, 1.07, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9518, 432068, 'tt5699154', NULL, 'C''est la vie!', 'Le Sens de la fête', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/e9hIxAKPdXo9Fgwca6vT4USOXK6.jpg', 'https://image.tmdb.org/t/p/original/10ECHyeW7vZMjCLSRLak9K5fVdB.jpg', 'Max is a battle-weary veteran of the wedding-planning racket. His latest — and last — gig is a hell of a fête, involving stuffy period costumes for the caterers, a vain, hyper- sensitive singer who thinks he''s a Gallic James Brown, and a morose, micromanaging groom determined to make Max''s night as miserable as possible. But what makes the affair too bitter to endure is that Max''s colleague and ostensible girlfriend, Joisette, seems to have written him off, coolly going about her professional duties while openly flirting with a much younger server. It''s going to be a very long night… especially once the groom''s aerial serenade gets underway.', NULL, NULL, 3.1744, 7.022, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
