INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9520, 16226, 'tt0354690', NULL, 'Lady Death', 'Lady Death', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/xVK9NOhb2jhkVqzTOjjnrQ3BUxk.jpg', 'https://image.tmdb.org/t/p/original/pP2FrpQdeUYHo7oYT59IEzkuozT.jpg', 'When accused by the townspeople of being in league with the Devil, Hope finds herself in a satanic deal for her life. After refusing the terms of the deal, she transforms into the powerful Lady Death and vows to wrest control of hell from her father.', NULL, NULL, 1.9755, 7.115, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9521, 60728, 'tt3114390', NULL, 'Kill la Kill', 'キルラキル', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/4F1WtP3dFIwLPOfa3u29VEVnNkf.jpg', 'https://image.tmdb.org/t/p/original/hsmYzDPyfiv3IlkxZsbeO92C7mP.jpg', 'Honnouji Academy is forcefully ruled by the iron-fisted control of its student council and its president, Satsuki Kiryuin. Transfer student, Ryuko Matoi, arrives on campus carrying a giant sword, that is actually half of a scissor. She is looking for the woman who holds the other half of her sword who killed her father. It is said that Satsuki Kiryuin knows the identity of the killer but when Ryuko confronts her she is beaten by the student council and their powerful "Goku Uniforms" whom she cannot match in strength. However, once Ryuko receives her own "Kamui" by the name of Senketsu, the odds are lifted in her favor.', NULL, NULL, 19.1252, 8.153, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9522, 72197, 'tt1430626', NULL, 'The Pirates! In an Adventure with Scientists!', 'The Pirates! In an Adventure with Scientists!', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/bkLeXPDP6sramrTiF5W7TzUl4t0.jpg', 'https://image.tmdb.org/t/p/original/9UZnCIeUVHzZQLDXN7lht2T4ndB.jpg', 'The enthusiastic Pirate Captain, along with his rag-tag crew, sets out to beat his bitter rivals. The chaotic adventure takes them from exotic shores to Victorian London, and from a haplessly smitten scientist to a diabolical queen.', NULL, NULL, 6.4457, 6.536, 0, 10.51, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9523, 1813, 'tt0111958', NULL, 'Father Ted', 'Father Ted', 'tv', 1995, 'https://image.tmdb.org/t/p/w500/hGgqGTVwZrifBX8T3f6ylqGFSXS.jpg', 'https://image.tmdb.org/t/p/original/wHv2m6JXB2nZcgshNQX3hggOK6N.jpg', 'A crazy comedy about three rather strange parish priests exiled to Craggy Island, a remote island off the Irish west coast.', NULL, NULL, 9.8354, 8.2, 0, 1.16, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9524, 62084, 'tt3636060', NULL, 'Poldark', 'Poldark', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/fTJZHMzlIGSJVPSe7Xz4p5SRwYP.jpg', 'https://image.tmdb.org/t/p/original/p8A1HMw3f3djxMwQRccCuxdy754.jpg', 'Britain is in the grip of a chilling recession... falling wages, rising prices, civil unrest - only the bankers are smiling. It''s 1783 and Ross Poldark returns from the American War of Independence to his beloved Cornwall to find his world in ruins: his father dead, the family mine long since closed, his house wrecked and his sweetheart pledged to marry his cousin. But Ross finds that hope and love can be found when you are least expecting it in the wild but beautiful Cornish landscape.', NULL, NULL, 22.5615, 7.727, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9525, 242879, 'tt27349314', NULL, 'The Last Night at Tremore Beach', 'La última noche en Tremor', 'tv', 2024, 'https://image.tmdb.org/t/p/w500/n1kwsyVHpC46af98UJr4J3MxZdg.jpg', 'https://image.tmdb.org/t/p/original/3mXXbck3errRlFt3icek4EkPI0I.jpg', 'When a tormented pianist is struck by lightning, he begins having perilous visions of his future and a deadly threat seems to loom over his loved ones.', NULL, NULL, 5.3779, 7.048, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9526, 39185, 'tt1693592', NULL, 'Vera', 'Vera', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/yeYImRVVEX6LM2151oEkmNUKLVR.jpg', 'https://image.tmdb.org/t/p/original/6LQdA5QPX7tjxPxD3l6hufGA2Ko.jpg', 'A sharp detective with a messy life, DCI Vera Stanhope patrols her “patch” of northeast England, pursuing the truth in cases of murder, kidnapping, and blackmail. Vera is obsessive about her work and faces the world with caustic wit, guile and courage.', NULL, NULL, 39.3549, 7.394, 0, 1.04, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9527, 205072, 'tt21161156', NULL, 'Beyond Paradise', 'Beyond Paradise', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/1zyKeMDCLpn2UK6hxU2IrVLgot2.jpg', 'https://image.tmdb.org/t/p/original/zlFXtd5UxmtgWfP5mxDYaaYAO3v.jpg', 'After leaving paradise and seeking a quieter life, Humphrey has taken a job as Detective Inspector in his fiancée Martha''s hometown. But with the high crime rate, maybe things will be louder than expected.', NULL, NULL, 12.8743, 6.931, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9528, 72748, 'tt4276618', NULL, 'Strike', 'Strike', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/9IF5DMeUcEaPXclFAfyMGP8CRg5.jpg', 'https://image.tmdb.org/t/p/original/x9yqsGeZjqmlCh5qVfhmFPp2kcH.jpg', 'A war veteran turned private detective operates out of a tiny office in London’s Denmark Street. Although wounded both physically and psychologically, his unique insight and background as a military police investigator prove crucial in solving complex crimes that have baffled the police. Based on the bestselling novels written by J.K. Rowling under the pseudonym Robert Galbraith.', NULL, NULL, 16.2088, 7.179, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9529, 34374, 'tt0079592', NULL, 'Murder by Decree', 'Murder by Decree', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/vjuO0XKak8v3uUdNjWr5sNIlJ4b.jpg', 'https://image.tmdb.org/t/p/original/xHZ4ws882XSmz6mYtDUyceRjKIx.jpg', 'Sherlock Holmes is drawn into the case of Jack the Ripper, who is killing prostitutes in London''s East End. Assisted by Dr. Watson, and using information provided by a renowned psychic, Robert Lees, Holmes finds that the murders may have their roots in a Royal indiscretion and that a cover-up is being managed by politicians at the highest level, all of whom happen to be Masons.', NULL, NULL, 2.5655, 6.346, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9530, 1177450, NULL, NULL, 'ICAC: Homeward Bound', 'ICAC：歸去來兮', 'movie', 1978, NULL, NULL, 'In “Homeward Bound”, the corrupt Health Inspector is not your usual villain; he spouts poetry and has a loving, dutiful wife. He''s also a sybarite who balances his life around a shrewd, money worshipping concubine and a mistress that is romantic, if impractical. His increasing desolation as all three women leave him is palpable and sagaciously reflects the ephemeral nature of life.', NULL, NULL, 1.5715, 0.0, 0, 10.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9531, 132064, 'tt1711018', NULL, 'Vile', 'Vile', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/wHxVSKv4plCpllQpBt4tOftKJ12.jpg', 'https://image.tmdb.org/t/p/original/mlCEa13EogQ7rYt96OglyjNzQam.jpg', 'A group of people awaken to find themselves prisoners in a mysterious house with no means of escape. They are each outfitted with electronic devices attached to the base of their skulls. The chemicals that the brain produces when in pain are collected by the devices, and when it collects a predetermined amount, the doors will be opened. In order to escape, they must hurt themselves and each other.', NULL, NULL, 1.8593, 5.065, 0, 1.0, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9532, 80741, 'tt8487786', NULL, 'Familiar Wife', '아는 와이프', 'tv', 2018, 'https://image.tmdb.org/t/p/w500/ds84fVavAJX872qh4kUHAfqjp3b.jpg', 'https://image.tmdb.org/t/p/original/pnKlgwSHfBcsz7zt4acZPwdvDlQ.jpg', 'After receiving a bizarre chance to go back in time, a man wakes up to find that his whole life — including the person he married — is different.', NULL, NULL, 5.0838, 8.044, 0, 1.08, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9533, 13318, 'tt0808185', NULL, 'The Bothersome Man', 'Den brysomme mannen', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/mHDeIKvmWYLyXwqXzN4F7Q2CHRT.jpg', 'https://image.tmdb.org/t/p/original/4oNqLwhCrABbf9L78YE3y5WIqrY.jpg', 'Forty-year-old Andreas arrives in a strange city with no memory of how he got there. He is presented with a job, an apartment - even a wife. But before long, Andreas notices that something is wrong. Andreas makes an attempt to escape the city, but he discovers there''s no way out. Andreas meets Hugo, who has found a crack in a wall in his cellar. Beautiful music streams out from the crack. Maybe it leads to "the other side"? A new plan for escape is hatched.', NULL, NULL, 2.5393, 7.065, 0, 9.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
