INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9569, 5552, 'tt0314063', NULL, 'Immortal', 'Immortel (ad vitam)', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/ryCZBW1iGlW70LGCswawI26AcBE.jpg', 'https://image.tmdb.org/t/p/original/1s9Gz5M2L2YWHkcxhcHwgXFD8c9.jpg', 'In the distant future, Earth is occupied by ancient gods and genetically altered humans. When a god is sentenced to death he seeks a new human host and a woman to bear his child.', NULL, NULL, 3.9753, 5.716, 0, 1.03, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9570, NULL, NULL, 26820, 'Blasphemous', 'Blasphemous', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0xj.jpg', NULL, 'Blasphemous is a punishing action-platformer that combines the fast-paced, skilled combat of a hack-n-slash game with a deep and evocative narrative core. Explore this nightmarish world of twisted religion and discover its many secrets hidden deep inside. Use devastating combos and brutal executions to smite the hordes of grotesque monsters and titanic bosses, who are all ready to rip your limbs off. Locate and equip relics, rosary beads and prayers that call on the powers of the heavens to aid you in your quest to break your eternal damnation.', 'https://www.igdb.com/games/blasphemous', '["PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.2, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9571, 37305, 'tt1214085', NULL, 'Soul Eater', 'ソウルイーター', 'tv', 2008, 'https://image.tmdb.org/t/p/w500/hAszc4fYfKU4SexxiSIigS3z2WU.jpg', 'https://image.tmdb.org/t/p/original/yOkNYWCOWLh3HFtUlo3QT1g5pHG.jpg', 'Set in the Shinigami technical school for weapon meisters, the series revolves around 3 groups of each a weapon meister and a human weapon. Trying to make the latter a "Death Scythe" which is the highest title for a weapon and thus fit for use by the Shinigami, they must collect the souls of 99 evil humans and 1 witch. Maka & Soul Eater, Black Star & Tsubaki, and Death the Kid with Patty and Liz Thompson are the characters Soul Eater revolves around. Besides taking the time to gather souls, these students of Shibusen defend Death City from some of the most powerful of creatures while still attending school and trying to become stronger.', NULL, NULL, 20.7757, 7.794, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9572, 2723, 'tt0278238', NULL, 'Samurai Jack', 'Samurai Jack', 'tv', 2001, 'https://image.tmdb.org/t/p/w500/ddZ7Q2WZ0xAHkVXYvcEgNGFgVkw.jpg', 'https://image.tmdb.org/t/p/original/CrVAqxtdmvelqVcj8pVeQg7wNV.jpg', 'A great warrior is displaced to the distant future by the evil shape-shifting wizard Aku. The world has become a bleak place under the rule of Aku, segregated into fantastic tribes and ruled by Aku''s evil robot warlords. Jack travels this foreign landscape in search of a time portal that can return him to his home time so he can "undo the future that is Aku!".', NULL, NULL, 31.0821, 8.4, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9573, NULL, NULL, 9577, 'Persona 3', 'Persona 3', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5mo6.jpg', NULL, 'Shin Megami Tensei: Persona 3 is a role-playing video game developed by Atlus. In the game, the player takes the role of a male high-school student who joins the Specialized Extracurricular Execution Squad (SEES), a group of students investigating the Dark Hour, a time period between one day and the next that few people are aware of. During the Dark Hour, the player enters Tartarus, a large tower containing Shadows, creatures that feed on the minds of humans. To fight the Shadows, each member of SEES is able to summon a Persona, a manifestation of a person''s inner self. In addition to the standard elements of role-playing games, Persona 3 includes elements of simulation games, as the game''s protagonist progresses day by day through a school year, making friends and forming relationships that improve the strength of his Personas in battle.', 'https://www.igdb.com/games/persona-3', '["PlayStation 2"]', NULL, NULL, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9574, 14282, 'tt0107692', NULL, 'Ninja Scroll', '獣兵衛忍風帖', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/qzZEnaXwv4wss2QalEo4Uf9BAwh.jpg', 'https://image.tmdb.org/t/p/original/mOd8oNCNyKOXs58FzdD1pPygWD.jpg', 'Jubei is a masterless ninja who travels the land alone, lending his services to those with gold—or a worthy cause. His fearsome abilities have served him well, but a plot to overthrow the government threatens to end his wandering ways—and possibly his life.', NULL, NULL, 5.4065, 7.792, 0, 1.02, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
