INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9630, 32628, 'tt0014538', NULL, 'Three Ages', 'Three Ages', 'movie', 1923, 'https://image.tmdb.org/t/p/w500/khadgoKp9eLBY4t0KcST5gzddk3.jpg', 'https://image.tmdb.org/t/p/original/3bS2SefEeu43bhbQ24EDiMBNtZs.jpg', 'The rituals of courtship, romantic rivalry, and love play out three times as a man vies with a villain for the girl. In the Stone Age, the rivalry is set off by dinosaurs, a turtle used as a ouija board, and a round of golf with stones. In ancient Rome, the men display their brawn through a chariot race, using dogs instead of horses. In contemporary times, the man finds himself overcome by modernity, including a very fragile car.', NULL, NULL, 1.8193, 6.824, 0, 1.04, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
