INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9633, 2277, 'tt0182789', NULL, 'Bicentennial Man', 'Bicentennial Man', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/wrs23eO0VEWwOQpXoOasMnlW9Y4.jpg', 'https://image.tmdb.org/t/p/original/aIVL5crQCBMPxKMoExiIsUDFPeR.jpg', 'Richard Martin buys a gift, a new NDR-114 robot. The product is named Andrew by the youngest of the family''s children. "Bicentennial Man" follows the life and times of Andrew, a robot purchased as a household appliance programmed to perform menial tasks. As Andrew begins to experience emotions and creative thought, the Martin family soon discovers they don''t have an ordinary robot.', NULL, NULL, 8.7842, 7.27, 0, 1.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9634, 313038, '', NULL, 'The Animatrix', 'The Animatrix', 'tv', 2003, 'https://image.tmdb.org/t/p/w500/3lKYUWSHUeKpfyBOjATX3GkSCzn.jpg', 'https://image.tmdb.org/t/p/original/yGZB773PqHUnuMVK5vrtpi20hJL.jpg', 'Straight from the creators of the groundbreaking Matrix trilogy, this collection of short animated films from the world''s leading anime directors fuses computer graphics and Japanese anime to provide the background of the Matrix universe and the conflict between man and machines. The shorts include Final Flight of the Osiris, The Second Renaissance, Kid''s Story, Program, World Record, Beyond, A Detective Story and Matriculated.', NULL, NULL, 5.0723, 7.625, 0, 2.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9635, 94329, 'tt1899353', NULL, 'The Raid', 'Serbuan Maut', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg', 'https://image.tmdb.org/t/p/original/3wf5wV222vqTmz10y1vbrPgrGDf.jpg', 'Deep in the heart of Jakarta''s slums lies an impenetrable safe house for the world''s most dangerous killers and gangsters. Until now, the run-down apartment block has been considered untouchable to even the bravest of police. Cloaked under the cover of pre-dawn darkness and silence, an elite swat team is tasked with raiding the safe house in order to take down the notorious drug lord that runs it.  But when a chance encounter with a spotter blows their cover and news of their assault reaches the drug lord, the building''s lights are cut and all the exits blocked. Stranded on the sixth floor with no way out, the unit must fight their way through the city''s worst to survive their mission. Starring Indonesian martial arts sensation Iko Uwais.', NULL, NULL, 8.5349, 7.407, 0, 2.01, '2026-08-11 22:09:33', '2026-08-11 22:09:33');
