UPDATE "recommendations" SET "tmdb_id"=82633, "imdb_id"='tt1212450', "igdb_id"=NULL, "title"='Lawless', "original_title"='Lawless', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/Ahtzwts22ayviD3LEVslfL4nRWB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6zTqEmFWlmmPPY907qwvv9WQBUm.jpg', "overview"='In 1931, the Bondurant brothers of Franklin County, Virginia, run a multipurpose backwoods establishment that hides their true business — bootlegging. Middle brother Forrest is the brain of the operation; older Howard is the brawn, and younger Jack, the lookout. Though the local police have taken bribes and left the brothers alone, a violent war erupts when a sadistic lawman from Chicago arrives and tries to shut down the Bondurants operation.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.1843, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=16.927, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 22:09:33' WHERE "id"=2569;
UPDATE "recommendations" SET "tmdb_id"=359940, "imdb_id"='tt5027774', "igdb_id"=NULL, "title"='Three Billboards Outside Ebbing, Missouri', "original_title"='Three Billboards Outside Ebbing, Missouri', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/fQzCvF2R4P9YkPQK7gO9LNLcnlD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oQHF0Y4gCw6VdPmapjsbZoxY2ht.jpg', "overview"='After seven months have passed without a culprit in her daughter''s murder case, Mildred Hayes makes a bold move, painting three signs leading into her town with a controversial message directed at Bill Willoughby, the town''s revered chief of police. When his second-in-command Officer Jason Dixon, an immature mother''s boy with a penchant for violence, gets involved, the battle between Mildred and Ebbing''s law enforcement is only exacerbated.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3006, "vote_average"=8.053, "is_ambiguous"=0, "evidence_score"=12.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 22:09:33' WHERE "id"=2573;
UPDATE "recommendations" SET "tmdb_id"=49637, "imdb_id"='tt1396227', "igdb_id"=NULL, "title"='The Wild and Wonderful Whites of West Virginia', "original_title"='The Wild and Wonderful Whites of West Virginia', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/7EQQsuK1Hk1zcoBlNBKfU41aS39.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2S0Kk3cMPE2CX0vEJ6Fp5OjPZgI.jpg', "overview"='Produced by Johnny Knoxville and Jeff Tremaine for MTV and Dickhouse Productions, The Wild and Wonderful Whites of West Virginia is a documentary about the renowned West Virginia outlaw Jesco White and his eccentric backwoods family. In addition to getting in trouble with the law, the Whites, who live deep within Appalachia, uphold a time-honored dancing style, even as they contend with poverty, drugs and other issues. Alternately humorous and sad, the movie is an unflinching look at life on the criminal margins of rural mountain culture.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.7399, "vote_average"=6.74, "is_ambiguous"=0, "evidence_score"=1.3442857142857143e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 22:09:33' WHERE "id"=2575;
