UPDATE "recommendations" SET "tmdb_id"=33324, "imdb_id"='tt0074605', "igdb_id"=NULL, "title"='Harlan County U.S.A.', "original_title"='Harlan County U.S.A.', "media_type"='movie', "release_year"=1977, "poster_url"='https://image.tmdb.org/t/p/w500/p0cyMNsoP5ap0omfhakhImBWTRw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pVspyFNl8uE8jAoY3C973XkjTgB.jpg', "overview"='This film documents the coal miners'' strike against the Brookside Mine of the Eastover Mining Company in Harlan County, Kentucky in June, 1973. Eastover''s refusal to sign a contract (when the miners joined with the United Mine Workers of America) led to the strike, which lasted more than a year and included violent battles between gun-toting company thugs/scabs and the picketing miners and their supportive women-folk. Director Barbara Kopple puts the strike into perspective by giving us some background on the historical plight of the miners and some history of the UMWA.  Preserved by the Academy Film Archive in partnership with New York Women in Film & Television in 2004.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.2183, "vote_average"=7.526, "is_ambiguous"=0, "evidence_score"=9.03666666666666706e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-11 22:09:33' WHERE "id"=2589;
