UPDATE "recommendations" SET "tmdb_id"=588228, "imdb_id"='tt9777666', "igdb_id"=NULL, "title"='The Tomorrow War', "original_title"='The Tomorrow War', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/34nDCQZwaEvsy4CFO5hkGRFDCVU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/yizL4cEKsVvl17Wc1mGEIrQtM2F.jpg', "overview"='The world is stunned when a group of time travelers arrive from the year 2051 to deliver an urgent message: Thirty years in the future, mankind is losing a global war against a deadly alien species. The only hope for survival is for soldiers and civilians from the present to be transported to the future and join the fight. Among those recruited is high school teacher and family man Dan Forester. Determined to save the world for his young daughter, Dan teams up with a brilliant scientist and his estranged father in a desperate quest to rewrite the fate of the planet.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.9853, "vote_average"=7.521, "is_ambiguous"=0, "evidence_score"=6.2525, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=2925;
