UPDATE "recommendations" SET "tmdb_id"=26963, "imdb_id"='tt0485601', "igdb_id"=NULL, "title"='The Secret of Kells', "original_title"='The Secret of Kells', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/vBymyj7QsXiW4TICD2JC5pAuBHO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/740KCabjLKjsrxvEakmmJtDtAGY.jpg', "overview"='Adventure awaits 12 year old Brendan who must fight Vikings and a serpent god to find a crystal and complete the legendary Book of Kells. In order to finish Brother Aiden''s book, Brendan must overcome his deepest fears on a secret quest that will take him beyond the abbey walls and into the enchanted forest where dangerous mythical creatures hide. Will Brendan succeed in his quest?', "external_url"=NULL, "platforms"=NULL, "popularity"=4.6114, "vote_average"=7.374, "is_ambiguous"=0, "evidence_score"=17.32, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3214;
