UPDATE "recommendations" SET "tmdb_id"=212778, "imdb_id"='tt2883512', "igdb_id"=NULL, "title"='Chef', "original_title"='Chef', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/hyp8EXDmO4dSC8V6Q5jU7gD1kcg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/igVNCpS132rOqrnDsrVYW5HCIsM.jpg', "overview"='When Chef Carl Casper suddenly quits his job at a prominent Los Angeles restaurant after refusing to compromise his creative integrity for its controlling owner, he is left to figure out what''s next. Finding himself in Miami, he teams up with his ex-wife, his friend and his son to launch a food truck. Taking to the road, Chef Carl goes back to his roots to reignite his passion for the kitchen -- and zest for life and love.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0474, "vote_average"=7.11, "is_ambiguous"=0, "evidence_score"=9.34, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3221;
UPDATE "recommendations" SET "tmdb_id"=562, "imdb_id"='tt0095016', "igdb_id"=NULL, "title"='Die Hard', "original_title"='Die Hard', "media_type"='movie', "release_year"=1988, "poster_url"='https://image.tmdb.org/t/p/w500/7Bjd8kfmDSOzpmhySpEhkUyK2oH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bvk2AAH64lP2YZs02Q3jskfHT8j.jpg', "overview"='High above the city of L.A. a team of terrorists has seized a building, taken hostages, and declared war. One man has manages to escape... An off-duty cop hiding somewhere inside. He''s alone, tired... and the only chance anyone has got.', "external_url"=NULL, "platforms"=NULL, "popularity"=24.4095, "vote_average"=7.814, "is_ambiguous"=0, "evidence_score"=7.51166666666666671e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3229;
UPDATE "recommendations" SET "tmdb_id"=85725, "imdb_id"='tt2202531', "igdb_id"=NULL, "title"='Salo', "original_title"='Salo', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/45s6eGZmvdt4PHSa486qwWTP50T.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/wTCbwBifX0nlX8kcGMC5MXZLZsm.jpg', "overview"='The rich yuppie Rene lives in his grandmother''s house, which he loves and adores. His driver Levi lives in the house, too. Rene focuses on his career entirely and goes to work every day. However, Rene has a dark secret: he loves men. One weekend he goes to his house by the sea with Levi. Overwhelmed by the masculine beauty and grace of Levi, Rene drops all restraints... it is a weekend that changes the lives of both forever.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9286, "vote_average"=3.625, "is_ambiguous"=0, "evidence_score"=6.36333333333333328e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3233;
UPDATE "recommendations" SET "tmdb_id"=163, "imdb_id"='tt0349903', "igdb_id"=NULL, "title"='Ocean''s Twelve', "original_title"='Ocean''s Twelve', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/pE5anFf7nf6ah7V3VRezQ1KSovi.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5b5HrewiViLWEdMR4dmbd7ajQ8Q.jpg', "overview"='Despite pulling off one of the biggest heists in Las Vegas history and splitting the $160 million take, each of the infamous Ocean''s crew have tried to go straight, lay low and live a legit life... but that''s proven to be a challenge. Casino owner Terry Benedict demands that Danny Ocean return the money, plus millions more in interest. Unable to come up the cash, the crew is forced to come together to pull off another series of heists, this time in Rome, Paris, and Amsterdam – but a Europol agent is hot on their heels.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.9846, "vote_average"=6.567, "is_ambiguous"=0, "evidence_score"=6.005, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3270;
