UPDATE "recommendations" SET "tmdb_id"=9408, "imdb_id"='tt0423294', "igdb_id"=NULL, "title"='Surf''s Up', "original_title"='Surf''s Up', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/tTDsCVlDA8QR4Dc6t6nERfwl5z.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/Y50RfoNVKIj9dSJavE8uBdN377.jpg', "overview"='With a documentary crew in tow, Cody Maverick—a young surfer from Antarctica—travels to the pacific for his first professional competition. Determined to earn respect and live up to his idol, Big Z, Cody pushes himself to the limit. But all that changes when an encounter with a laid-back local forces him to rethink his values.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.0479, "vote_average"=6.515, "is_ambiguous"=0, "evidence_score"=1.04633333333333329e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3450;
UPDATE "recommendations" SET "tmdb_id"=9266, "imdb_id"='tt0300532', "igdb_id"=NULL, "title"='Blue Crush', "original_title"='Blue Crush', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/iZSw0JVG0cIFuZoTHuQU3nmGT4k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xsVMKdSndUKid3Xm3Tudf5bcOlv.jpg', "overview"='Nothing gets between Anne Marie and her board. Living in a beach shack with three roommates, she is up before dawn every morning to conquer the waves and count the days until the Pipe Masters competition. Having transplanted herself to Hawaii with no one''s blessing but her own, Anne Marie finds all she needs in the adrenaline-charged surf scene - until pro quarterback Matt Tollman comes along...', "external_url"=NULL, "platforms"=NULL, "popularity"=3.495, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=2.0626842105263158e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3451;
UPDATE "recommendations" SET "tmdb_id"=14361, "imdb_id"='tt0103924', "igdb_id"=NULL, "title"='Captain Ron', "original_title"='Captain Ron', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/otnKFXvqFH2swlrNf2sNiXpnIsR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cUqa9ngoI72dFGVQKVLsTbzj65B.jpg', "overview"='When mild-mannered Martin Harvey finds out that he has inherited a vintage yacht, he decides to take his family on a Caribbean vacation to retrieve the vessel. Upon arriving on a small island and realizing that the ship is in rough shape, Martin and his family end up with more than they bargained for as the roguish Captain Ron signs on to sail the boat to Miami. It doesn''t take long before Ron''s anything-goes antics get the Harveys into plenty of trouble.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5511, "vote_average"=5.593, "is_ambiguous"=0, "evidence_score"=1.2911999999999999e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3458;
UPDATE "recommendations" SET "tmdb_id"=10276, "imdb_id"='tt0103241', "igdb_id"=NULL, "title"='What About Bob?', "original_title"='What About Bob?', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/pFCrGGGhV5xeAdvEysv6aSv8T13.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2Ek1JtggvRquMfzie66ybbID9g0.jpg', "overview"='Before going on vacation, self-involved psychiatrist Dr. Leo Marvin has the misfortune of taking on a new patient: Bob Wiley. An exemplar of neediness and a compendium of phobias, Bob follows Marvin to his family''s country house. Dr. Marvin tries to get him to leave; the trouble is, everyone loves Bob. As his oblivious patient makes himself at home, Dr. Marvin loses his professional composure and, before long, may be ready for the loony bin himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.8997, "vote_average"=6.885, "is_ambiguous"=0, "evidence_score"=1.43833333333333328e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-11 22:09:33' WHERE "id"=3482;
