UPDATE "recommendations" SET "tmdb_id"=2430, "imdb_id"='tt0408381', "igdb_id"=NULL, "title"='Doc Martin', "original_title"='Doc Martin', "media_type"='tv', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/zmd4ZpdXWnjKVrenqvYyYstOkwK.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/g0LCSXvweUAMW8jB3O2ECMwDAua.jpg', "overview"='Doc Martin is a British television comedy drama series starring Martin Clunes in the title role. It was created by Dominic Minghella after the character of Dr. Martin Bamford in the 2000 comedy film Saving Grace. The show is set in the fictional seaside village of Portwenn and filmed on location in the village of Port Isaac, Cornwall, England, with most interior scenes shot in a converted local barn. Five series aired between 2004 and 2011, together with a feature-length special that aired on Christmas Day 2006. Series 6 began airing on ITV on 2 September 2013.', "external_url"=NULL, "platforms"=NULL, "popularity"=23.4663, "vote_average"=8.275, "is_ambiguous"=0, "evidence_score"=6.07333333333333325e+00, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-11 22:09:33' WHERE "id"=4460;
