UPDATE "recommendations" SET "tmdb_id"=111, "imdb_id"='tt0086250', "igdb_id"=NULL, "title"='Scarface', "original_title"='Scarface', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1qM2BYNE11Viby8ImC9LC00DgDr.jpg', "overview"='After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.', "external_url"=NULL, "platforms"=NULL, "popularity"=20.1201, "vote_average"=8.155, "is_ambiguous"=0, "evidence_score"=2.75969230769230797e+01, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-11 22:09:33' WHERE "id"=4553;
