UPDATE "recommendations" SET "tmdb_id"=38543, "imdb_id"='tt1233301', "igdb_id"=NULL, "title"='Ironclad', "original_title"='Ironclad', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/h7CP12wAThhw2WSOA1uIAqxg1fS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rprg34i9MfIRAJdBcjAWaV7JXRe.jpg', "overview"='In the year 1215, the rebel barons of England have forced their despised King John to put his royal seal on the Magna Carta, a seminal document that upheld the rights of free men. Yet within months of pledging himself to the great charter, the King reneged on his word and assembled a mercenary army on the south coast of England with the intention of bringing the barons and the country back under his tyrannical rule. Barring his way stood the mighty Rochester castle, a place that would become the symbol of the rebel''s momentous struggle for justice and freedom.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7969, "vote_average"=6.151, "is_ambiguous"=0, "evidence_score"=3.01, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-11 22:09:33' WHERE "id"=4579;
