UPDATE "recommendations" SET "tmdb_id"=819797, "imdb_id"='tt8630356', "igdb_id"=NULL, "title"='The Ghost Image - On the set of Ghostland', "original_title"='L''image Fantôme - Sur le tournage de Ghostland', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/joZdPwmqHIG4T7XxSo7p7B2GkhH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/144vyWpKeukro8emE4cXdCwQedV.jpg', "overview"='During the fall of 2016 in Winnipeg, Canada, Pascal Laugier, accompanied by his troupe of actors, set to work on the production of his fourth feature film. Get up close and personal with those involved as they share their doubts, their joys, and their desires. Experience the arduous filming of Incident in a Ghostland alongside those who brought it to life.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.7816, "vote_average"=7.5, "is_ambiguous"=0, "evidence_score"=3.02, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-11 22:09:33' WHERE "id"=5264;
