UPDATE "recommendations" SET "tmdb_id"=942486, "imdb_id"='tt0171583', "igdb_id"=NULL, "title"='The Moravian Land', "original_title"='O moravské zemi', "media_type"='movie', "release_year"=1978, "poster_url"='https://image.tmdb.org/t/p/w500/mUUeHl94lG0Q0lJefjLUqwiU9Gj.jpg', "backdrop_url"=NULL, "overview"='The reason for making this film is clear: it was to cover up Vojtěch Jasný''s famous chronicle "All the Good Natives", an account of the tragic consequences of forced collectivisation. The pro-regime director Antonín Kachlík also focuses on the socialisation of the Moravian village, accompanied by mistakes and coercion, but in his optimistic view he emphasises the hopeful prospects leading to a happy future. Although the united village lands were born in pain, they will serve for the benefit of all the working people... As with Jasný, Radek Brzobohatý embodies the stubborn peasant, who is only slowly acknowledging the benefits of communal farming. However, unlike the poetic exuberance and pithiness of Jasný''s chronicle, here we encounter a vicious posturing.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.1118, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=2.02, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-11 22:09:33' WHERE "id"=5285;
UPDATE "recommendations" SET "tmdb_id"=11675, "imdb_id"='tt0120694', "igdb_id"=NULL, "title"='Halloween H20: 20 Years Later', "original_title"='Halloween H20: 20 Years Later', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/lqLXUm3oK59sGJKRH2Zjj2m3iMg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/A1LU0zDxrEhtMYpqDHbXkBJT6aP.jpg', "overview"='Two decades after surviving a massacre on October 31, 1978, former baby sitter Laurie Strode finds herself hunted by persistent knife-wielder Michael Myers. Laurie now lives in Northern California under an assumed name, where she works as the headmistress of a private school. But it''s not far enough to escape Myers, who soon discovers her whereabouts. As Halloween descends upon Laurie''s peaceful community, a feeling of dread weighs upon her -- with good reason.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.7325, "vote_average"=6.05, "is_ambiguous"=0, "evidence_score"=5.68333333333333357e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-11 22:09:33' WHERE "id"=5301;
