UPDATE "recommendations" SET "tmdb_id"=4480, "imdb_id"='tt0091288', "igdb_id"=NULL, "title"='Jean de Florette', "original_title"='Jean de Florette', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/atjyDRdOnOi2S28X3mNtJ7CQmFj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qNBxyt60hnzBRSHo1uRkRU34fYE.jpg', "overview"='In a rural French village, an old man and his only remaining relative cast their covetous eyes on an adjoining vacant property. They need its spring water for growing their flowers, and are dismayed to hear that the man who has inherited it is moving in. They block up the spring and watch as their new neighbour tries to keep his crops watered from wells far afield through the hot summer. Though they see his desperate efforts are breaking his health and his wife and daughter''s hearts, they think only of getting the water.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.0892, "vote_average"=7.679, "is_ambiguous"=0, "evidence_score"=8.67666666666666586e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-11 22:09:33' WHERE "id"=5589;
