UPDATE "recommendations" SET "tmdb_id"=84327, "imdb_id"='tt2125666', "igdb_id"=NULL, "title"='The Queen of Versailles', "original_title"='The Queen of Versailles', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/eFMRyapxD7XP5Boj6CLaDtQ1m3o.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9kjM8bRLcMRhOgX3z6MVw24n5Al.jpg', "overview"='With the epic dimensions of a Shakespearean tragedy, The Queen of Versailles follows billionaires Jackie and David’s rags-to-riches story to uncover the innate virtues and flaws of their American dream. We open on the triumphant construction of the biggest house in America, a sprawling, 90,000-square-foot mansion inspired by Versailles. Since a booming time-share business built on the real-estate bubble is financing it, the economic crisis brings progress to a halt and seals the fate of its owners. We witness the impact of this turn of fortune over the next two years in a riveting film fraught with delusion, denial, and self-effacing humor.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9929, "vote_average"=6.912, "is_ambiguous"=0, "evidence_score"=5.028, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-11 22:09:33' WHERE "id"=5591;
