UPDATE "recommendations" SET "tmdb_id"=24836, "imdb_id"='tt0412467', "igdb_id"=NULL, "title"='August Underground', "original_title"='August Underground', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/4zdKBTOl4I6fOcXNWeecT0RXpLB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/d5LywdMQJRGcKMR6dXuUYXtAcqJ.jpg', "overview"='Imagine walking down the street and finding an unmarked VHS tape. Curiosity piqued, you take it home and pop it in. What starts off as two men screwing around with a video camera quickly transforms into an ultra-realistic torture sequence where the unidentified psychopaths tape their exploits as they torment and violate a woman tied to a chair. The devastation of your morals continues throughout the entirety of the footage, while subtly revealing the killer''s shattered pasts via the interaction with their victims and each other.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.2018, "vote_average"=4.08, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-11 22:09:33' WHERE "id"=7047;
