UPDATE "recommendations" SET "tmdb_id"=3482, "imdb_id"='tt0059825', "igdb_id"=NULL, "title"='The Train', "original_title"='The Train', "media_type"='movie', "release_year"=1964, "poster_url"='https://image.tmdb.org/t/p/w500/bzgPLB7efMohled42PIn6CcOTnO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tL5uUcgmpcCZOnrnjPcNwz1LGqY.jpg', "overview"='As the Allied forces approach Paris in August 1944, German Colonel Von Waldheim is desperate to take all of France''s greatest paintings to Germany. He manages to secure a train to transport the valuable art works even as the chaos of retreat descends upon them. The French resistance however wants to stop them from stealing their national treasures but have received orders from London that they are not to be destroyed. The station master, Labiche, is tasked with scheduling the train and making it all happen smoothly but he is also part of a dwindling group of resistance fighters tasked with preventing the theft. He and others stage an elaborate ruse to keep the train from ever leaving French territory.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5102, "vote_average"=7.6, "is_ambiguous"=0, "evidence_score"=6.04666666666666685e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-11 22:09:33' WHERE "id"=7124;
