UPDATE "recommendations" SET "tmdb_id"=100402, "imdb_id"='tt1843866', "igdb_id"=NULL, "title"='Captain America: The Winter Soldier', "original_title"='Captain America: The Winter Soldier', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/tVFRpFw3xTedgPGqxW0AOI8Qhh0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1RWLMyC9KcFfcaoViMiJGSSZzzr.jpg', "overview"='After the cataclysmic events in New York with The Avengers, Steve Rogers, aka Captain America is living quietly in Washington, D.C. and trying to adjust to the modern world. But when a S.H.I.E.L.D. colleague comes under attack, Steve becomes embroiled in a web of intrigue that threatens to put the world at risk. Joining forces with the Black Widow, Captain America struggles to expose the ever-widening conspiracy while fighting off professional assassins sent to silence him at every turn. When the full scope of the villainous plot is revealed, Captain America and the Black Widow enlist the help of a new ally, the Falcon. However, they soon find themselves up against an unexpected and formidable enemy—the Winter Soldier.', "external_url"=NULL, "platforms"=NULL, "popularity"=21.5094, "vote_average"=7.655, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-11 22:09:33' WHERE "id"=8054;
