UPDATE "recommendations" SET "tmdb_id"=63147, "imdb_id"='tt1719634', "igdb_id"=NULL, "title"='Snow on tha Bluff', "original_title"='Snow on tha Bluff', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/vXGArJcQG14TcLVsmFO8BEEI7Ar.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/o8TJBedg2RGRwzGfSg0qhcSTpYD.jpg', "overview"='When Curtis Snow steals a video camera from some college kids during a dope deal, he gives the camera to his best friend, Pancho, and they start documenting their lives. At first its business as usual for Curtis. He robs dope boys, he runs from the cops, he sells drugs, all while trying to provide for his two-year-old son. But when one of the dealers he ripped off comes for revenge, Curt’s life starts to spiral out of control.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9788, "vote_average"=6.3, "is_ambiguous"=0, "evidence_score"=5.01500000000000056e+00, "created_at"='2026-08-08 02:23:49', "updated_at"='2026-08-11 22:09:33' WHERE "id"=8161;
