UPDATE "recommendations" SET "tmdb_id"=266880, "imdb_id"='tt3661072', "igdb_id"=NULL, "title"='Giuseppe Makes a Movie', "original_title"='Giuseppe Makes a Movie', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/84wEpo82TdGQV8yO7bv1yNw3wtf.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aJYPRoBlv2dRjFGWyA2xxLHXCJd.jpg', "overview"='While the rest of America slept, DIY filmmaker/musician Giuseppe Andrews has made over 30 experimental features. Set in some demented alternate universe (i.e. Ventura, California), they are populated by real-life alcoholics and drug addicts, trash-talking senior citizens and trailer park residents dressed in cow outfits and costume-shop wigs. Director Adam Rifkin creates a wildly surreal, outrageously funny and strangely touching portrait of a truly Outsider Artist inhabiting a world few of us even know exists.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.6775, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=2.035, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-11 22:09:33' WHERE "id"=8628;
