UPDATE "recommendations" SET "tmdb_id"=14275, "imdb_id"='tt0110057', "igdb_id"=NULL, "title"='Hoop Dreams', "original_title"='Hoop Dreams', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/gLzHl2XBtVwycl8DxdOXRHPm8G3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pYeiEm55NySzK9ksKlQGlFQNapz.jpg', "overview"='Every school day, African-American teenagers William Gates and Arthur Agee travel 90 minutes each way from inner-city Chicago to St. Joseph High School in Westchester, Illinois, a predominately white suburban school well-known for the excellence of its basketball program. Gates and Agee dream of NBA stardom, and with the support of their close-knit families, they battle the social and physical obstacles that stand in their way. This acclaimed documentary was shot over the course of five years.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.603, "vote_average"=7.6, "is_ambiguous"=0, "evidence_score"=5.505, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-11 22:09:33' WHERE "id"=8793;
